using Godot;
using System.Collections.Generic;
using Settings=Godot.Collections.Dictionary;
public partial class ActorInspectorOperations
{
    private readonly TimelinePhysicsOperations _timelinePhysics=new();private readonly DebrisDefinitionOperations _debris=new();private readonly FluidSettingsOperations _fluidSettings=new();
    public bool add_special_property(Control owner,Resource property,Resource definition,VBoxContainer parent)
    {
        var options=property.Get("options").AsGodotDictionary();var actor=Ui<Resource>(owner,"_actor");var model=Ui<RefCounted>(owner,"model");bool Option(string name)=>options.GetValueOrDefault(name,false).AsBool();string id=actor.Get("id").AsString();var updaters=owner.Get("_updaters").AsGodotArray();if(Option("environment_open")){var button=new Button{Text="Open Environment Creator ↗",Disabled=actor.Get("values").AsGodotDictionary().GetValueOrDefault("environment_path","").AsString().Length==0};parent.AddChild(button);button.Pressed+=()=>owner.GetTree().GetFirstNodeInGroup("actor_scene_tabs")?.Call("open_environment",actor.Get("values").AsGodotDictionary().GetValueOrDefault("environment_path",""));return true;}if(Option("fog_motion_status")){var label=new Label{AutowrapMode=TextServer.AutowrapMode.WordSmart};label.AddThemeFontSizeOverride("font_size",12);parent.AddChild(label);void Update(){label.Text="CPU reference transport · use a local domain for physical motion.";foreach(var editor in owner.GetTree().GetNodesInGroup("actor_timeline_editors")){if(editor.Get("model").AsGodotObject()!=model)continue;var runtime=_timelinePhysics.runtime(editor.Get("physics").As<RefCounted>(),id);if(runtime==null)continue;var stats=runtime.GetMeta("fog_motion_stats",new Settings()).AsGodotDictionary();if(stats.Count>0)label.Text=$"{stats["cells"].AsInt32()} cells · step {stats["cpu_ms"].AsDouble():F2} ms · upload {stats["upload_ms"].AsDouble():F2} ms\nConcentration volume {stats["mass"].AsDouble():F3} · outflow / decay {stats["lost"].AsDouble():F3}\n{stats["error"]}";}}Update();updaters.Add(Callable.From(Update));return true;}
        string script=Option("fog_presets")?"fog/fog_control":Option("fragment_director")||Option("destruction_workflow")?"physics/destruction/destruction_workflow_control":Option("damage_presets")?"physics/destruction/destruction_material_control":Option("destruction_editor")?"physics/destruction/destruction_control":Option("structure_editor")?"physics/structure/structure_control":"";if(script.Length>0){Control control=script switch { "physics/destruction/destruction_material_control" => new DestructionMaterialControl(), "physics/destruction/destruction_control" => new DestructionControl(), "physics/structure/structure_control" => new StructureControl(), _ => GD.Load<GDScript>("res://scripts/actors/"+script+".gd").New().As<Control>() };parent.AddChild(control);if(script.EndsWith("destruction_workflow_control"))control.Call("setup",owner,actor,Option("destruction_workflow"));else control.Call("setup",owner,actor);return true;}if(Option("debris_copy")){var button=new Button{Text="Copy debris to editable actors",TooltipText="Copy current fragments as ordinary mesh actors in one undo action. Originals remain intact; copied actors start with physics disabled to avoid double simulation."};parent.AddChild(button);button.Pressed+=()=>{foreach(var editor in owner.GetTree().GetNodesInGroup("actor_timeline_editors"))if(editor.Get("model").AsGodotObject()==model)_debris.copy_fragments(editor,actor);};return true;}if(Option("powder_presets")){owner.Call("_add_powder_preset_browser",parent,actor);return true;}
        if(actor.Get("type_id").AsString()=="powder"&&property.Get("id").AsString()=="powder_enabled"){var status=new Label{Name="PowderStatus",AutowrapMode=TextServer.AutowrapMode.WordSmart};status.AddThemeFontSizeOverride("font_size",12);parent.AddChild(status);void Update(){foreach(var editor in owner.GetTree().GetNodesInGroup("actor_timeline_editors")){if(editor.Get("model").AsGodotObject()!=model)continue;var state=editor.Get("physics").AsGodotObject().Get("display_states").AsGodotDictionary().GetValueOrDefault(id,new Settings()).AsGodotDictionary();status.Text=state.GetValueOrDefault("powder_error","").AsString();if(status.Text.Length==0)status.Text=state.GetValueOrDefault("powder_warning","").AsString();if(status.Text.Length==0)status.Text=$"{state.GetValueOrDefault("points",System.Array.Empty<Vector3>()).AsVector3Array().Length} grains · {(_data.get_value(actor,"powder_simulate",true).AsBool()?"Granular simulation":"Source preview only")}";}}Update();updaters.Add(Callable.From(Update));}
        if(actor.Get("type_id").AsString()=="fluid"&&property.Get("id").AsString()=="fluid_preset"){add_label(parent,"Liquid preset");var choice=new OptionButton{Name="FluidPreset"};parent.AddChild(choice);foreach(var title in options["choices"].AsGodotArray())choice.AddItem(title.AsString());choice.Select(actor.Get("values").AsGodotDictionary().GetValueOrDefault("fluid_preset",0).AsInt32());choice.ItemSelected+=index=>{_fluidSettings.preset(model,actor,(int)index);owner.Call("_queue_rebuild_selected");};return true;}if(Option("transformation_image")){owner.Call("_add_transformation_editor",property,definition,parent);return true;}if(Option("actor_reference")){owner.Call("_add_actor_reference",property,definition,parent);return true;}return false;
    }
}
